import './workshop.js?v=195';
import './game86.js?v=195';
const $=id=>document.getElementById(id);
const icons={explore:'M4 20V7l8-4 8 4v13M8 20v-7h8v7M8 8h8',maintenance:'m14 6 4-3 3 3-3 4-4-1-8 11-3-3 10-8z',operator:'M4 18a8 8 0 1 1 16 0M12 16l5-7M5 20h14',automatic:'M5 4h14v14H5zM8 8h8M8 12h8M8 18l-2 3m10-3 2 3'};
for(const b of document.querySelectorAll('[data-game-mode]')){const svg=document.createElement('span');svg.className='game92-mode-icon';svg.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="${icons[b.dataset.gameMode]}"/></svg>`;b.prepend(svg);}
const hud=document.createElement('div');hud.id='game92-hud';hud.innerHTML='<span class="game92-live-dot"></span><span id="game92-location">CENTRO DE EXPERIENCIAS</span><span id="game92-progress"></span>';document.querySelector('header').append(hud);
if(!document.getElementById('maintenance-hands-panel').dataset.rebuild102){
const tools=document.createElement('div');tools.className='game92-repair-actions';tools.innerHTML='<button id="game92-refocus">↗ Encuadrar banco</button><button id="game92-release">Soltar pieza · Esc</button><span>1–5 Herramientas · Clic o arrastrar · Botón derecho para desplazar</span>';$('maintenance-hands-panel').prepend(tools);
const repairRoot=$('maintenance-hands-panel'),layout=repairRoot.querySelector('.hands-layout'),cards=repairRoot.querySelector('.repair-case-cards'),toolbar=repairRoot.querySelector('.hands-tools');
repairRoot.insertBefore(toolbar,cards.nextSibling);repairRoot.insertBefore(layout,toolbar.nextSibling);repairRoot.insertBefore(repairRoot.querySelector('.repair-status-strip'),layout);repairRoot.querySelector('.repair-board-toolbar').append(tools);const actions93=repairRoot.querySelector('.repair93-actions'),message93=$('hands-live-message');if(actions93)message93.parentElement.insertBefore(actions93,message93);const manual=repairRoot.querySelector('.hands-manual-card');manual.insertBefore(repairRoot.querySelector('.mission-controls'),$('hands-progress'));manual.insertBefore($('hands-symptom'),$('hands-instruction'));$('hands-focus').textContent='Centrar banco';
for(const [i,b]of [...document.querySelectorAll('[data-tool]')].entries()){b.dataset.hotkey=String(i+1);b.title=`${i+1} · ${b.textContent}`;}
$('game92-refocus').onclick=()=>window.metroRepair?.focus();$('game92-release').onclick=()=>window.metroRepair?.cancel();
}
function status(){const screen=document.body.dataset.gameScreen;const names={home:'CENTRO DE EXPERIENCIAS',depot:'DEPÓSITO · SELECCIONAR TREN',loading:'PREPARANDO MODELO',detail:'EXPLORACIÓN DE COMPONENTES',maintenance:'MISIÓN DE MANTENIMIENTO',simulation:document.body.dataset.driving==='true'?'CABINA · CONDUCCIÓN':'RECORRIDOS · OBSERVACIÓN'};$('game92-location').textContent=names[screen]||'METRO CDMX';let records={};try{records=JSON.parse(localStorage.getItem('metro-repairs82')||'{}');}catch{}$('game92-progress').textContent=Object.keys(records).length+' / 4 misiones';if(screen==='maintenance'){$('workshop').hidden=false;$('maintenance-hands-panel').hidden=false;}}
new MutationObserver(status).observe(document.body,{attributes:true,attributeFilter:['data-game-screen','data-driving']});window.addEventListener('workshop-mode',status);window.addEventListener('metro-repair-completed',status);status();
window.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||document.body.dataset.gameScreen!=='maintenance'||document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;if(e.key==='Escape'&&(window.metroRepair?.state.selectedItem||window.metroRepair?.state.toolMotion)){e.preventDefault();e.stopImmediatePropagation();window.metroRepair.cancel();}const b=document.querySelector(`[data-tool][data-hotkey="${e.key.replace(/[^1-5]/g,'')}"]`);if(b&&/^[1-5]$/.test(e.key)){e.preventDefault();b.click();}if(e.key.toLowerCase()==='f'){e.preventDefault();window.metroRepair?.focus();}},true);
